	QVERIFY(before);
	QVERIFY(before->hasWorldVariablesSnapshot);
	QCOMPARE(before->worldVariablesSnapshot.value(QStringLiteral("stale")).content,
	         QStringLiteral("present"));

	QCOMPARE(runtime.deleteVariable(QStringLiteral("stale")), eOK);

